import{_ as a,o,c as l,aw as e}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Cookie","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/client-storage/cookie.md","filePath":"wiki/dev-commit/js/js-web-api/client-storage/cookie.md"}'),n={name:"wiki/dev-commit/js/js-web-api/client-storage/cookie.md"};function i(p,s,t,c,r,y){return o(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="cookie" tabindex="-1">Cookie <a class="header-anchor" href="#cookie" aria-label="Permalink to &quot;Cookie&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://learn.javascript.ru/cookie" target="_blank" rel="noreferrer">https://learn.javascript.ru/cookie</a></p></div><ul><li><strong>Cookie</strong> - небольшой объем именованных данных (в текстовом виде), отправленный веб-сервером и хранимый в браузере пользователя</li><li>Данные cookie автоматически передаются между веб-браузером и веб-сервером в составе HTTP-запроса, так что серверные сценарии могут читать и записывать значения cookie, сохраняемые на стороне клиента.</li></ul><h3 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to &quot;Применение&quot;">​</a></h3><ul><li>Аутентификация пользователя</li><li>Хранение персональных предпочтений и настроек пользователя</li><li>Отслеживание состояния сеанса доступа пользователя</li><li>Сведения статистики о пользователях</li></ul><h3 id="особенности" tabindex="-1">Особенности <a class="header-anchor" href="#особенности" aria-label="Permalink to &quot;Особенности&quot;">​</a></h3><ul><li>Данные отправляются обратно на сервер для каждого HTTP-запроса</li><li>Работают только на веб-сервере</li></ul><h3 id="ограничения" tabindex="-1">Ограничения <a class="header-anchor" href="#ограничения" aria-label="Permalink to &quot;Ограничения&quot;">​</a></h3><ul><li>Не больше 300 Cookie для сайта. При превышении лимита самые старые файлы перезаписываются</li><li>Размер одной Cookie не больше 4КБ. При превышении, самые старые байты перезаписываются</li><li>От одного домена (второго уровня, включая поддомены) может быть установлено не более 20 Cookie</li><li>Для конкретного сайта будут доступны только те Cookie, которые им были установлены</li></ul><h2 id="флаг-httponly" tabindex="-1">Флаг httpOnly <a class="header-anchor" href="#флаг-httponly" aria-label="Permalink to &quot;Флаг httpOnly&quot;">​</a></h2><ul><li>Флаг httpOnly позволяет сделать доступной Cookie только с сервера, js не может получить доступ к Cookie</li><li>В cookie можно положить Refresh Token</li></ul><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> express</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> require</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;express&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> cookie</span><span style="color:#0184BC;"> =</span><span style="color:#4078F2;"> require</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;cookie&quot;</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> authRouter</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> express.</span><span style="color:#4078F2;">Router</span><span style="color:#383A42;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">authRouter.</span><span style="color:#4078F2;">get</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;/logout&quot;</span><span style="color:#383A42;">, (req, res) </span><span style="color:#A626A4;">=&gt;</span><span style="color:#383A42;"> {</span></span>
<span class="line"><span style="color:#383A42;">	res.</span><span style="color:#4078F2;">setHeader</span><span style="color:#383A42;">(</span></span>
<span class="line"><span style="color:#50A14F;">		&quot;Set-Cookie&quot;</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#383A42;">		cookie.</span><span style="color:#4078F2;">serialize</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;refreshToken&quot;</span><span style="color:#383A42;">, </span><span style="color:#50A14F;">&quot;&quot;</span><span style="color:#383A42;">, {</span></span>
<span class="line"><span style="color:#E45649;">			httpOnly</span><span style="color:#0184BC;">:</span><span style="color:#986801;"> true</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#E45649;">			maxAge</span><span style="color:#0184BC;">:</span><span style="color:#986801;"> 0</span><span style="color:#383A42;">,</span></span>
<span class="line"><span style="color:#383A42;">		})</span></span>
<span class="line"><span style="color:#383A42;">	);</span></span>
<span class="line"><span style="color:#383A42;">	res.</span><span style="color:#4078F2;">sendStatus</span><span style="color:#383A42;">(</span><span style="color:#986801;">200</span><span style="color:#383A42;">);</span></span>
<span class="line"><span style="color:#383A42;">});</span></span></code></pre></div><h2 id="типы-куки" tabindex="-1">Типы куки <a class="header-anchor" href="#типы-куки" aria-label="Permalink to &quot;Типы куки&quot;">​</a></h2><ol><li>Сессионные куки (временные) - существуют только во временной памяти, пока пользователь находится на странице веб-сайта. Браузеры обычно удаляют сессионные куки после того, как пользователь закрывает окно браузера. В отличие от других типов куки, сессионные куки не имеют истечения срока действия</li><li>Постоянные куки - удаляются в определённую дату или через определённый промежуток времени. Это означает, что информация о куки будет передаваться на сервер каждый раз, когда пользователь посещает веб-сайт, которому эти куки принадлежат</li><li>Защищенные куки - могут быть переданы только через шифрованное соединение (HTTPS). Они не могут передаваться по незащищенным соединениям. Чтобы защитить куки, необходимо добавить флаг secure в файл куки</li><li>HttpOnly-куки - нельзя обращаться с помощью API на стороне клиента, таких как JS</li></ol><p>\`</p><h2 id="атрибуты-cookie" tabindex="-1">Атрибуты cookie <a class="header-anchor" href="#атрибуты-cookie" aria-label="Permalink to &quot;Атрибуты cookie&quot;">​</a></h2><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">document.</span><span style="color:#E45649;">cookie</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> \`</span></span>
<span class="line"><span style="color:#50A14F;">	info=123;</span></span>
<span class="line"><span style="color:#50A14F;">	expires=Fri, 31 Dec 2018 23:59:59 GMT;</span></span>
<span class="line"><span style="color:#50A14F;">	path=/;</span></span>
<span class="line"><span style="color:#50A14F;">	domain=.example.org</span></span>
<span class="line"><span style="color:#50A14F;">\`</span><span style="color:#383A42;">;</span></span></code></pre></div><ul><li>name - имя</li><li>value - значение</li><li>expires - по умолчанию cookies являются временными (сеансовыми) - их значения сохраняются на период сеанса браузера и теряются при закрытии сеанса пользователем. Чтобы cookie сохранялся после окончания сеанса, необходимо сообщить браузеру, как долго он должен храниться. Атрибут expires указывает дату окончания действия cookie. Значение expires (RFC 2616) записывается в формате &quot;Wdy, DD Mon YYYY HH:MM:SS GMT&quot;. Если этот атрибут не задан, то cookie хранится в течение одного сеанса, до закрытия браузера.</li><li>max age - аналогичен атрибуту expires, но срок хранения определяется в секундах (RFC 6265). Значение десятичное неотрицательное целое число. По истечении заданного времени клиент должен отказаться от куки. Значение &quot;0&quot; означает, что от cookie нужно отказаться немедленно.</li><li>Установка значения любого из этих атрибутов(expires, max age) заставляет браузер сохранить cookie в локальном файле, чтобы он мог быть прочитан при следующем посещении пользователем веб страницы. После того как будет достигнута дата окончания действия expires или истечет период max age, браузер автоматически удалит cookie файл.</li><li>path - задает веб-страницы, с которыми связан cookie. По умолчанию cookie связывается с создавшей его веб страницей и доступен этой же странице, а также любой другой странице из того же каталога или любых его подкаталогов.</li><li>Этого правила видимости, принятого по умолчанию, обычно вполне достаточно. Тем не менее иногда значения cookie файла требуется использовать на всем многостраничном веб сайте независимо от того, какая страница создала cookie. Чтобы это можно было сделать, для cookie файла задается значение path(path=/😉. Тогда любая страница того же веб сервера, содержащая указанное значение в своем URL, сможет использовать cookie файл.</li><li>domain - по умолчанию cookies доступны только страницам, загружаемым с того веб-сервера, который их установил. Однако, большим веб-сайтам может потребоваться возможность совместного использования cookies несколькими веб серверами. Если атрибут domain для cookie не установлен, значением по умолчанию будет имя веб сервера, на котором находится страница. НЕЛЬЗЯ сделать так, чтобы домен cookie файла отличался от домена вашего сервера.</li><li>secure - логический атрибут, определяющий, как значения cookie файла передаются по сети. По умолчанию cookie не защищен, т.е. передается по обычному незащищенному HTTP соединению. Однако если cookie помечен как защищенный, он передается, только когда обмен между браузером и сервером организован по протоколу HTTPS или другому защищенному протоколу. По умолчанию принимает значение false.</li></ul><h2 id="установка-cookie-через-javascript" tabindex="-1">Установка cookie через JavaScript <a class="header-anchor" href="#установка-cookie-через-javascript" aria-label="Permalink to &quot;Установка cookie через JavaScript&quot;">​</a></h2><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// установить cookie (удаляются при закрытии браузера)</span></span>
<span class="line"><span style="color:#383A42;">document.</span><span style="color:#E45649;">cookie</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &#39;info=123&#39;</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// установить cookie (удалятся 31.12.2000)</span></span>
<span class="line"><span style="color:#383A42;">document.</span><span style="color:#E45649;">cookie</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &#39;info=123; expires=Fri, 31 Dec 2000 23:59:59 GMT&#39;</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// прочитать cookie</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> cookie</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> document.</span><span style="color:#E45649;">cookie</span><span style="color:#383A42;">;</span></span></code></pre></div><h2 id="дополнительно" tabindex="-1">Дополнительно <a class="header-anchor" href="#дополнительно" aria-label="Permalink to &quot;Дополнительно&quot;">​</a></h2><h3 id="сторонние-cookie" tabindex="-1">Сторонние cookie <a class="header-anchor" href="#сторонние-cookie" aria-label="Permalink to &quot;Сторонние cookie&quot;">​</a></h3><ul><li>Хотя cookies отправляются только на серверы домена, для которого они предназначены, веб-страница может подгружать изображения или другие компоненты из других доменов. Cookies, получаемые во время загрузки этих компонентов из других доменов, называются &quot;сторонними&quot;.</li><li>Рекламные компании используют сторонние куки для отслеживания перемещений пользователя по сайтам. В частности, рекламная компания может отслеживать пользователей на всех сайтах, где установлены их рекламные баннеры. Знание страниц, посещённых пользователем, позволяет менять направленность рекламы в зависимости от предпочтений пользователя.</li></ul><h3 id="приватность" tabindex="-1">Приватность <a class="header-anchor" href="#приватность" aria-label="Permalink to &quot;Приватность&quot;">​</a></h3><ul><li>Создание профиля пользователей рассматривается как потенциальная угроза приватности даже при отслеживании в рамках одного домена, но особенно это актуально при отслеживания на нескольких доменах с использованием сторонних куки. По этой причине в некоторых странах cookies регулируются законодательством.</li><li>Спецификация P3P включает возможность для веб-сервера сообщить браузеру о нарушении конфиденциальности, указывая характер собираемой информации и цели сбора. Сюда входит и использование информации, полученной с помощью куки. По спецификации P3P браузер может принимать или отклонять куки согласно пользовательским настройкам или же спросить пользователя.</li></ul><h3 id="рекомендации-по-созданию-cookies-фаилов" tabindex="-1">Рекомендации по созданию cookies-файлов <a class="header-anchor" href="#рекомендации-по-созданию-cookies-фаилов" aria-label="Permalink to &quot;Рекомендации по созданию cookies-файлов&quot;">​</a></h3><ul><li>Пользователь при помощи JavaScript может изменить cookies-файлы. Более того, существует возможность заменить сессионные куки постоянными. Серверное программное обеспечение должно отслеживать такие попытки. Для этого сервер выдаёт куки на определённый срок и записывает дату окончания куки у себя каждый раз, когда пользователь обращается к серверу. Если куки, присланный браузером, имеет дату действия отличную от той, что хранится на сервере, значит имеет место попытка подмены даты действия куки. Сервер может отреагировать, например, запросив у пользователя повторную авторизацию. Или изначально установить флаг HttpOnly в заголовке Методы и структура протокола HTTP Set-Cookie, который делает cookies недоступными для скриптов со стороны клиента.</li><li>На сервере обычно хранят время последней активности пользователя. И время действия куки зависит от типа ресурса, например на форумах от 3 дней, до месяца, на админских панелях 1 день.</li><li>При начале новой сессии ID (уникальную строку) в файле куки нужно менять каждый раз. Это нужно для безопасности, чтобы другой человек похитив эту ID- строку не мог пользоваться аккаунтом жертвы постоянно. Также строку нужно менять при каждом вводе пользователем логина и пароля.</li></ul>`,27)])])}const h=a(n,[["render",i]]);export{u as __pageData,h as default};
